parameters.functionCode:
const tasks = $input.first().json.result || [];

// Find DD tasks
const ddTasks = tasks.filter(task => 
  task.title && task.title.toLowerCase().includes('due diligence:')
);

if (ddTasks.length === 0) {
  console.log('No DD tasks found');
  throw new Error('No Due Diligence tasks found');
}

// Select first DD task
const task = ddTasks[0];

// Validate prerequisites
const errors = [];

if (!task.title.includes('Due Diligence:')) {
  errors.push('Title missing company name');
}

let websiteUrl = '';
try {
  const urlMatch = task.description ? task.description.match(/https?:\/\/[^\s]+/) : null;
  if (urlMatch) {
    websiteUrl = urlMatch[0];
  } else {
    errors.push('No website URL found in description');
  }
} catch (e) {
  errors.push('Invalid website URL');
}

// Extract company name
const companyName = task.title.replace(/due diligence:\s*/i, '').trim();

return {
  json: {
    taskId: task.id,
    projectId: task.project_id || 1,
    companyName,
    websiteUrl,
    errors,
    description: task.description || ''
  }
};

// Build Knowledge Base from website
const taskData = $('Validate Task').first().json;
let websiteContent = '';

try {
  const websiteResponse = $('Fetch Website').first();
  if (websiteResponse && websiteResponse.data) {
    websiteContent = websiteResponse.data.toString();
  }
} catch (error) {
  console.log('Website fetch failed:', error.message);
}

// Create knowledge base chunks
let kbChunks = [];

// Add task info
kbChunks.push({
  chunk_id: `kb://${taskData.taskId}/task:title`,
  content: `Company: ${taskData.companyName}. Task: ${taskData.title || 'Due Diligence: ' + taskData.companyName}`,
  source_type: 'task_info'
});

kbChunks.push({
  chunk_id: `kb://${taskData.taskId}/task:description`,
  content: `Task Description: ${taskData.description}`,
  source_type: 'task_info'
});

// Add website chunks if available
if (websiteContent) {
  const chunks = chunkText(websiteContent, 800);
  chunks.forEach((chunk, index) => {
    kbChunks.push({
      chunk_id: `kb://${taskData.taskId}/website:${index + 1}`,
      content: chunk,
      source_type: 'website'
    });
  });
}

function chunkText(text, maxTokens) {
  const words = text.split(/\s+/);
  const chunks = [];
  let currentChunk = [];

  for (const word of words) {
    currentChunk.push(word);
    if (currentChunk.length >= maxTokens * 0.75) {
      chunks.push(currentChunk.join(' '));
      currentChunk = [];
    }
  }

  if (currentChunk.length > 0) {
    chunks.push(currentChunk.join(' '));
  }

  return chunks;
}

console.log(`Built KB with ${kbChunks.length} chunks`);

return {
  json: {
    ...taskData,
    kbChunks: kbChunks,
    totalChunks: kbChunks.length
  }
};

// Generate section list
const sections = [
  'Business Model & Unit Economics',
  'Company Overview',
  'Products & Technology',
  'Target Market & Competitive Set',
  'Financials'
];

const taskData = $input.first().json;

// For this demo, process first section
const currentSection = sections[0];

return {
  json: {
    ...taskData,
    currentSection: currentSection,
    allSections: sections
  }
};

// Parse Checker response
const taskData = $('Get Next Section').first().json;
const makerResponse = $('Maker LLM').first().json.response;
const checkerResponse = $input.first().json.response;

let checkerData;
try {
  // Try to parse JSON from response
  const jsonMatch = checkerResponse.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    checkerData = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found');
  }
} catch (e) {
  checkerData = {
    approved: false,
    quality_score: 1,
    issues: ['Checker response invalid: ' + e.message],
    instructions: 'Checker failed to return valid JSON'
  };
}

console.log(`Checker result: ${checkerData.approved ? 'APPROVED' : 'REJECTED'} (Score: ${checkerData.quality_score}/10)`);

return {
  json: {
    ...taskData,
    makerOutput: makerResponse,
    checkerData: checkerData
  }
};

