// Parse Approver response
const taskData = $input.first().json;
const approverResponse = $('Approver LLM').first().json.response;

let approverData;
try {
  // Try to parse JSON from response
  const jsonMatch = approverResponse.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    approverData = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found');
  }
} catch (e) {
  approverData = {
    approved: false,
    feedback: 'Approver response invalid: ' + e.message,
    instructions: 'Approver failed to return valid JSON'
  };
}

console.log(`Approver result: ${approverData.approved ? 'APPROVED' : 'REJECTED'}`);

if (approverData.approved) {
  // Generate final comment
  const finalComment = `🎉 **DUE DILIGENCE ANALYSIS COMPLETED**\n\n` +
    `📄 **Company:** ${taskData.companyName}\n` +
    `📝 **Section:** ${taskData.currentSection}\n` +
    `**Quality Score:** ${taskData.checkerData.quality_score}/10\n` +
    `**Generated:** ${new Date().toISOString()}\n\n` +
    `---\n\n` +
    taskData.makerOutput +
    `\n\n---\n\n` +
    `## Quality Assurance\n\n` +
    `**Checker:** ✅ Approved (${taskData.checkerData.quality_score}/10)\n` +
    `**Approver:** ✅ Approved\n` +
    `**Knowledge Base:** ${taskData.totalChunks} chunks\n` +
    `\n⏰ **Completed:** ${new Date().toISOString()}`;

  return {
    json: {
      ...taskData,
      approverData: approverData,
      finalComment: finalComment,
      approved: true
    }
  };
} else {
  return {
    json: {
      ...taskData,
      approverData: approverData,
      approved: false
    }
  };
}
